+  force = force === true;
+  if (test.isPending() && !force) {
+    return;
+  }
+  if (this.state === constants.STATE_STOPPED) {
+    if (err.code === errorConstants.MULTIPLE_DONE) {
+      throw err;
+    }
+    throw createFatalError(
+      'Test failed after root suite execution completed!',
+      err
+    );
+  }
