+  Runner.immediately(function () {
+    next(0);
+  });
+};
+
+/**
+ * Run hook `name` for the given array of `suites`
+ * in order, and callback `fn(err, errSuite)`.
+ *
+ * @private
+ * @param {string} name
+ * @param {Array} suites
+ * @param {Function} fn
+ */
+Runner.prototype.hooks = function (name, suites, fn) {
+  var self = this;
+  var orig = this.suite;
+
+  function next(suite) {
+    self.suite = suite;
+
+    if (!suite) {
+      self.suite = orig;
+      return fn();
+    }
+
+    self.hook(name, function (err) {
+      if (err) {
+        var errSuite = self.suite;
+        self.suite = orig;
+        return fn(err, errSuite);
+      }
+
+      next(suites.pop());
+    });
+  }
+
+  next(suites.pop());
+};
+
+/**
+ * Run 'afterEach' hooks from bottom up.
+ *
+ * @param {String} name
+ * @param {Function} fn
+ * @private
+ */
+Runner.prototype.hookUp = function (name, fn) {
+  var suites = [this.suite].concat(this.parents()).reverse();
+  this.hooks(name, suites, fn);
+};
+
+/**
+ * Run 'beforeEach' hooks from top level down.
+ *
+ * @param {String} name
+ * @param {Function} fn
+ * @private
+ */
+Runner.prototype.hookDown = function (name, fn) {
+  var suites = [this.suite].concat(this.parents());
+  this.hooks(name, suites, fn);
+};
+
+/**
+ * Return an array of parent Suites from
+ * closest to furthest.
+ *
+ * @return {Array}
+ * @private
+ */
+Runner.prototype.parents = function () {
+  var suite = this.suite;
+  var suites = [];
+  while (suite.parent) {
+    suite = suite.parent;
+    suites.push(suite);
+  }
+  return suites;
+};
+
+/**
+ * Run the current test and callback `fn(err)`.
+ *
+ * @param {Function} fn
+ * @private
+ */
+Runner.prototype.runTest = function (fn) {
+  if (this._opts.dryRun) return Runner.immediately(fn);
+
+  var self = this;
+  var test = this.test;
+
+  if (!test) {
+    return;
+  }
+
+  if (this.asyncOnly) {
+    test.asyncOnly = true;
+  }
+  this._addEventListener(test, 'error', function (err) {
+    self.fail(test, err);
+  });
+  if (this.allowUncaught) {
+    test.allowUncaught = true;
+    return test.run(fn);
+  }
+  try {
+    test.run(fn);
+  } catch (err) {
+    fn(err);
+  }
+};
+
+/**
+ * Run tests in the given `suite` and invoke the callback `fn()` when complete.
+ *
+ * @private
+ * @param {Suite} suite
+ * @param {Function} fn
+ */
+Runner.prototype.runTests = function (suite, fn) {
+  var self = this;
+  var tests = suite.tests.slice();
+  var test;
+
+  function hookErr(_, errSuite, after) {
+    // before/after Each hook for errSuite failed:
+    var orig = self.suite;
+
+    // for failed 'after each' hook start from errSuite parent,
+    // otherwise start from errSuite itself
+    self.suite = after ? errSuite.parent : errSuite;
+
+    if (self.suite) {
+      self.hookUp(HOOK_TYPE_AFTER_EACH, function (err2, errSuite2) {
+        self.suite = orig;
+        // some hooks may fail even now
+        if (err2) {
+          return hookErr(err2, errSuite2, true);
+        }
+        // report error suite
+        fn(errSuite);
+      });
+    } else {
+      // there is no need calling other 'after each' hooks
+      self.suite = orig;
+      fn(errSuite);
+    }
+  }
+
+  function next(err, errSuite) {
+    // if we bail after first err
+    if (self.failures && suite._bail) {
+      tests = [];
+    }
+
+    if (self._abort) {
+      return fn();
+    }
+
+    if (err) {
+      return hookErr(err, errSuite, true);
+    }
+
+    // next test
+    test = tests.shift();
+
+    // all done
+    if (!test) {
+      return fn();
+    }
+
+    // grep
+    var match = self._grep.test(test.fullTitle());
+    if (self._invert) {
+      match = !match;
+    }
+    if (!match) {
+      // Run immediately only if we have defined a grep. When we
+      // define a grep — It can cause maximum callstack error if
+      // the grep is doing a large recursive loop by neglecting
+      // all tests. The run immediately function also comes with
+      // a performance cost. So we don't want to run immediately
+      // if we run the whole test suite, because running the whole
+      // test suite don't do any immediate recursive loops. Thus,
+      // allowing a JS runtime to breathe.
+      if (self._grep !== self._defaultGrep) {
+        Runner.immediately(next);
+      } else {
+        next();
+      }
+      return;
+    }
+
+    // static skip, no hooks are executed
+    if (test.isPending()) {
+      if (self.forbidPending) {
+        self.fail(test, new Error('Pending test forbidden'), true);
+      } else {
+        test.state = STATE_PENDING;
+        self.emit(constants.EVENT_TEST_PENDING, test);
+      }
+      self.emit(constants.EVENT_TEST_END, test);
+      return next();
+    }
+
+    // execute test and hook(s)
+    self.emit(constants.EVENT_TEST_BEGIN, (self.test = test));
+    self.hookDown(HOOK_TYPE_BEFORE_EACH, function (err, errSuite) {
+      // conditional skip within beforeEach
+      if (test.isPending()) {
+        if (self.forbidPending) {
+          self.fail(test, new Error('Pending test forbidden'), true);
+        } else {
+          test.state = STATE_PENDING;
+          self.emit(constants.EVENT_TEST_PENDING, test);
+        }
+        self.emit(constants.EVENT_TEST_END, test);
+        // skip inner afterEach hooks below errSuite level
+        var origSuite = self.suite;
+        self.suite = errSuite || self.suite;
+        return self.hookUp(HOOK_TYPE_AFTER_EACH, function (e, eSuite) {
+          self.suite = origSuite;
+          next(e, eSuite);
+        });
+      }
+      if (err) {
+        return hookErr(err, errSuite, false);
+      }
+      self.currentRunnable = self.test;
+      self.runTest(function (err) {
+        test = self.test;
+        // conditional skip within it
+        if (test.pending) {
+          if (self.forbidPending) {
+            self.fail(test, new Error('Pending test forbidden'), true);
+          } else {
+            test.state = STATE_PENDING;
+            self.emit(constants.EVENT_TEST_PENDING, test);
+          }
+          self.emit(constants.EVENT_TEST_END, test);
+          return self.hookUp(HOOK_TYPE_AFTER_EACH, next);
+        } else if (err) {
+          var retry = test.currentRetry();
+          if (retry < test.retries()) {
+            var clonedTest = test.clone();
+            clonedTest.currentRetry(retry + 1);
+            tests.unshift(clonedTest);
+
+            self.emit(constants.EVENT_TEST_RETRY, test, err);
+
+            // Early return + hook trigger so that it doesn't
+            // increment the count wrong
+            return self.hookUp(HOOK_TYPE_AFTER_EACH, next);
+          } else {
+            self.fail(test, err);
+          }
+          self.emit(constants.EVENT_TEST_END, test);
+          return self.hookUp(HOOK_TYPE_AFTER_EACH, next);
+        }
+
+        test.state = STATE_PASSED;
+        self.emit(constants.EVENT_TEST_PASS, test);
+        self.emit(constants.EVENT_TEST_END, test);
+        self.hookUp(HOOK_TYPE_AFTER_EACH, next);
+      });
+    });
+  }
+
+  this.next = next;
+  this.hookErr = hookErr;
+  next();
+};
+
+/**
+ * Run the given `suite` and invoke the callback `fn()` when complete.
+ *
+ * @private
+ * @param {Suite} suite
+ * @param {Function} fn
+ */
+Runner.prototype.runSuite = function (suite, fn) {
+  var i = 0;
+  var self = this;
+  var total = this.grepTotal(suite);
+
+  debug('runSuite(): running %s', suite.fullTitle());
+
+  if (!total || (self.failures && suite._bail)) {
+    debug('runSuite(): bailing');
+    return fn();
+  }
+
+  this.emit(constants.EVENT_SUITE_BEGIN, (this.suite = suite));
+
+  function next(errSuite) {
+    if (errSuite) {
+      // current suite failed on a hook from errSuite
+      if (errSuite === suite) {
+        // if errSuite is current suite
+        // continue to the next sibling suite
+        return done();
+      }
+      // errSuite is among the parents of current suite
+      // stop execution of errSuite and all sub-suites
+      return done(errSuite);
+    }
+
+    if (self._abort) {
+      return done();
+    }
+
+    var curr = suite.suites[i++];
+    if (!curr) {
+      return done();
+    }
+
+    // Avoid grep neglecting large number of tests causing a
+    // huge recursive loop and thus a maximum call stack error.
+    // See comment in `this.runTests()` for more information.
+    if (self._grep !== self._defaultGrep) {
+      Runner.immediately(function () {
+        self.runSuite(curr, next);
+      });
+    } else {
+      self.runSuite(curr, next);
+    }
+  }
+
+  function done(errSuite) {
+    self.suite = suite;
+    self.nextSuite = next;
+
+    // remove reference to test
+    delete self.test;
+
+    self.hook(HOOK_TYPE_AFTER_ALL, function () {
+      self.emit(constants.EVENT_SUITE_END, suite);
+      fn(errSuite);
+    });
+  }
+
+  this.nextSuite = next;
+
+  this.hook(HOOK_TYPE_BEFORE_ALL, function (err) {
+    if (err) {
+      return done();
+    }
+    self.runTests(suite, next);
+  });
+};
+
+/**
+ * Handle uncaught exceptions within runner.
+ *
+ * This function is bound to the instance as `Runner#uncaught` at instantiation
+ * time. It's intended to be listening on the `Process.uncaughtException` event.
+ * In order to not leak EE listeners, we need to ensure no more than a single
+ * `uncaughtException` listener exists per `Runner`.  The only way to do
+ * this--because this function needs the context (and we don't have lambdas)--is
+ * to use `Function.prototype.bind`. We need strict equality to unregister and
+ * _only_ unregister the _one_ listener we set from the
+ * `Process.uncaughtException` event; would be poor form to just remove
+ * everything. See {@link Runner#run} for where the event listener is registered
+ * and unregistered.
+ * @param {Error} err - Some uncaught error
+ * @private
+ */
+Runner.prototype._uncaught = function (err) {
+  // this is defensive to prevent future developers from mis-calling this function.
+  // it's more likely that it'd be called with the incorrect context--say, the global
+  // `process` object--than it would to be called with a context that is not a "subclass"
+  // of `Runner`.
+  if (!(this instanceof Runner)) {
+    throw createFatalError(
+      'Runner#uncaught() called with invalid context',
+      this
+    );
+  }
+  if (err instanceof Pending) {
+    debug('uncaught(): caught a Pending');
+    return;
+  }
+  // browser does not exit script when throwing in global.onerror()
+  if (this.allowUncaught && !utils.isBrowser()) {
+    debug('uncaught(): bubbling exception due to --allow-uncaught');
+    throw err;
+  }
+
+  if (this.state === constants.STATE_STOPPED) {
+    debug('uncaught(): throwing after run has completed!');
+    throw err;
+  }
+
+  if (err) {
+    debug('uncaught(): got truthy exception %O', err);
+  } else {
+    debug('uncaught(): undefined/falsy exception');
+    err = createInvalidExceptionError(
+      'Caught falsy/undefined exception which would otherwise be uncaught. No stack trace found; try a debugger',
+      err
+    );
+  }
+
+  if (!isError(err)) {
+    err = thrown2Error(err);
+    debug('uncaught(): converted "error" %o to Error', err);
+  }
+  err.uncaught = true;
+
+  var runnable = this.currentRunnable;
+
+  if (!runnable) {
+    runnable = new Runnable('Uncaught error outside test suite');
+    debug('uncaught(): no current Runnable; created a phony one');
+    runnable.parent = this.suite;
+
+    if (this.state === constants.STATE_RUNNING) {
+      debug('uncaught(): failing gracefully');
+      this.fail(runnable, err);
+    } else {
+      // Can't recover from this failure
+      debug('uncaught(): test run has not yet started; unrecoverable');
+      this.emit(constants.EVENT_RUN_BEGIN);
+      this.fail(runnable, err);
+      this.emit(constants.EVENT_RUN_END);
+    }
+
+    return;
+  }
+
+  runnable.clearTimeout();
+
+  if (runnable.isFailed()) {
+    debug('uncaught(): Runnable has already failed');
+    // Ignore error if already failed
+    return;
+  } else if (runnable.isPending()) {
+    debug('uncaught(): pending Runnable wound up failing!');
+    // report 'pending test' retrospectively as failed
+    this.fail(runnable, err, true);
+    return;
+  }
+
+  // we cannot recover gracefully if a Runnable has already passed
+  // then fails asynchronously
+  if (runnable.isPassed()) {
+    debug('uncaught(): Runnable has already passed; bailing gracefully');
+    this.fail(runnable, err);
+    this.abort();
+  } else {
+    debug('uncaught(): forcing Runnable to complete with Error');
+    return runnable.callback(err);
+  }
+};
+
+/**
+ * Run the root suite and invoke `fn(failures)`
+ * on completion.
+ *
+ * @public
+ * @memberof Runner
+ * @param {Function} fn - Callback when finished
+ * @param {Object} [opts] - For subclasses
+ * @param {string[]} opts.files - Files to run
+ * @param {Options} opts.options - command-line options
+ * @returns {Runner} Runner instance.
+ */
+Runner.prototype.run = function (fn, opts = {}) {
+  var rootSuite = this.suite;
+  var options = opts.options || {};
+
+  debug('run(): got options: %O', options);
+  fn = fn || function () {};
+
+  const end = () => {
+    if (!this.total && this._opts.failZero) this.failures = 1;
+
+    debug('run(): root suite completed; emitting %s', constants.EVENT_RUN_END);
+    this.emit(constants.EVENT_RUN_END);
+  };
+
+  const begin = () => {
+    debug('run(): emitting %s', constants.EVENT_RUN_BEGIN);
+    this.emit(constants.EVENT_RUN_BEGIN);
+    debug('run(): emitted %s', constants.EVENT_RUN_BEGIN);
+
+    this.runSuite(rootSuite, end);
+  };
+
+  const prepare = () => {
+    debug('run(): starting');
+    // If there is an `only` filter
+    if (rootSuite.hasOnly()) {
+      rootSuite.filterOnly();
+      debug('run(): filtered exclusive Runnables');
+    }
+    this.state = constants.STATE_RUNNING;
+    if (this._opts.delay) {
+      this.emit(constants.EVENT_DELAY_END);
+      debug('run(): "delay" ended');
+    }
+
+    return begin();
+  };
+
+  // references cleanup to avoid memory leaks
+  if (this._opts.cleanReferencesAfterRun) {
+    this.on(constants.EVENT_SUITE_END, suite => {
+      suite.cleanReferences();
+    });
+  }
+
+  // callback
+  this.on(constants.EVENT_RUN_END, function () {
+    this.state = constants.STATE_STOPPED;
+    debug('run(): emitted %s', constants.EVENT_RUN_END);
+    fn(this.failures);
+  });
+
+  this._removeEventListener(process, 'uncaughtException', this.uncaught);
+  this._removeEventListener(process, 'unhandledRejection', this.unhandled);
+  this._addEventListener(process, 'uncaughtException', this.uncaught);
+  this._addEventListener(process, 'unhandledRejection', this.unhandled);
+
+  if (this._opts.delay) {
+    // for reporters, I guess.
+    // might be nice to debounce some dots while we wait.
+    this.emit(constants.EVENT_DELAY_BEGIN, rootSuite);
+    rootSuite.once(EVENT_ROOT_SUITE_RUN, prepare);
+    debug('run(): waiting for green light due to --delay');
+  } else {
+    Runner.immediately(prepare);
+  }
+
+  return this;
+};
+
+/**
