+{
+  "name": "mocha",
+  "version": "11.1.0",
+  "type": "commonjs",
+  "description": "simple, flexible, fun test framework",
+  "keywords": [
+    "mocha",
+    "test",
+    "bdd",
+    "tdd",
+    "tap",
+    "testing",
+    "chai",
+    "assertion",
+    "ava",
+    "jest",
+    "tape",
+    "jasmine",
+    "karma"
+  ],
+  "author": "TJ Holowaychuk <tj@vision-media.ca>",
